def completitud(ruta_rel: str) -> str:
    """Public CI documentation."""
    if ruta_rel in COMPLETITUD_DECLARADA:
        return COMPLETITUD_DECLARADA[ruta_rel]
    n = ruta_rel.rsplit('/', 1)[-1].upper()
    if 'PREVIEW' in n:
        return 'preview'
    if 'EXTRACTO' in n or 'ABSTRACT' in n:
        return 'extracto'
    if 'PARCIAL' in n or 'TRUNCADO' in n or 'pags1-' in ruta_rel:
        return 'parcial'
    return 'completa'
