def familia(ruta_rel: str) -> str | None:
    if ruta_rel in NT_TROCEADAS:
        return NT_TROCEADAS[ruta_rel]
    if ruta_rel in FAMILIA_EXPLICITA:
        return FAMILIA_EXPLICITA[ruta_rel]
    for carpeta, fam in FAMILIA_POR_DEFECTO.items():
        if ruta_rel.startswith(carpeta):
            return fam
    return None
