def aplazado(ruta_rel: str) -> bool:
    nombre = ruta_rel.replace('\\', '/').rsplit('/', 1)[-1].casefold()
    return any((n.casefold() == nombre for n in DOCUMENTOS_APLAZADOS_V2A))

