RE_ANO = re.compile('(?:^|[_\\-])((?:19|20)\\d{2})(?:[_\\-.]|$)')

def edicion_de(ruta_rel: str) -> str | None:
    """Public CI documentation."""
    declarada = METADATOS_POR_DOCUMENTO.get(ruta_rel, {}).get('edicion')
    if declarada:
        return declarada
    nombre = ruta_rel.rsplit('/', 1)[-1].rsplit('.', 1)[0]
    anos = RE_ANO.findall(nombre)
    return anos[-1] if anos else None
EMISOR_POR_PREFIJO = (('BOE_', 'Boletín Oficial del Estado'), ('DOUE_', 'Diario Oficial de la Unión Europea'), ('EC_', 'Comisión Europea'), ('CEM-UPM_', 'Centro Español de Metrología y UPM'), ('CEM_GUM_JCGM', 'JCGM'), ('CEM_JCGM', 'JCGM'), ('JCGM_', 'JCGM'), ('CEM_', 'Centro Español de Metrología'), ('EMISOR_DEMO_FR', 'Emisor_Demo_Fr'), ('RCM_', 'Registro de Control Metrológico'), ('WELMEC_', 'WELMEC'), ('EA_', 'European co-operation for Accreditation'), ('ILAC_', 'ILAC'), ('OIML_', 'OIML'), ('EURAMET_', 'EURAMET'), ('ETSI_', 'ETSI'), ('ENAC_', 'ENAC'), ('UNECE_', 'UNECE'), ('OMS_', 'Organización Mundial de la Salud'), ('PICS_', 'PIC/S'), ('NIST_', 'NIST'), ('ENISA_', 'ENISA'), ('CCN-STIC_', 'Centro Criptológico Nacional'), ('ISO_', 'ISO'), ('BS_EN_', 'British Standards Institution'), ('EN_', 'CEN/CENELEC'), ('EN-', 'CEN/CENELEC'), ('UNE-EN', 'UNE'), ('SIST', 'SIST'), ('EMISOR_DEMO_AUX_', 'Emisor_Demo_Es'))
IDIOMAS_CONOCIDOS = {'en': 'en', 'es': 'es', 'fr': 'fr', 'ru': 'ru', 'de': 'de', 'it': 'it', 'enfr': 'enfr', 'esen': 'esen'}
IDIOMAS_SOLO_AL_FINAL = frozenset(('de',))
SUFIJOS_DE_ESTADO = frozenset(('vigente', 'anulada', 'anulado', 'derogada', 'derogado', 'borrador', 'preview', 'parcial', 'completa', 'completo', 'truncado', 'extracto', 'abstract', 'obligatorio', 'informativo', 'consolidado', 'consolidada', 'original', 'sist', 'din', 'une', 'borrable'))
RE_PAGINAS = re.compile('^(?:pags?\\d|\\d+p)$', re.I)
IDIOMA_DE_DOCUMENTO = {'01_Conocimiento/Fuentes_primarias/02_Legislacion_UE/NORMA_PAGO_21.pdf': 'en', '01_Conocimiento/Fuentes_primarias/02_Legislacion_UE/NORMA_PAGO_22.pdf': 'en', '01_Conocimiento/Fuentes_primarias/03_Guias_CEM_WELMEC/NORMA_PAGO_69.pdf': 'en'}

def idioma_de(ruta_rel: str) -> str | None:
    """Public CI documentation."""
    if ruta_rel in IDIOMA_DE_DOCUMENTO:
        return IDIOMA_DE_DOCUMENTO[ruta_rel]
    nombre = ruta_rel.rsplit('/', 1)[-1].rsplit('.', 1)[0]
    trozos = [t for t in re.split('[_\\-]', nombre) if t]
    mirados = 0
    for t in reversed(trozos):
        b = t.lower()
        if b in SUFIJOS_DE_ESTADO or RE_PAGINAS.match(b):
            continue
        if b in IDIOMAS_CONOCIDOS and (mirados == 0 or b not in IDIOMAS_SOLO_AL_FINAL):
            return IDIOMAS_CONOCIDOS[b]
        mirados += 1
        if mirados >= 4:
            break
    return None

def emisor_de(ruta_rel: str) -> str | None:
    """Public CI documentation."""
    n = ruta_rel.rsplit('/', 1)[-1]
    for prefijo, emisor in EMISOR_POR_PREFIJO:
        if n.startswith(prefijo):
            return emisor
    return None

def metadatos(ruta_rel: str) -> dict:
    return METADATOS_POR_DOCUMENTO.get(ruta_rel, {})
