def titulo_oficial(identificador: str | None) -> str | None:
    """Public CI documentation."""
    t = TITULOS_OFICIALES.get(identificador) if identificador else None
    return ' '.join(t) if isinstance(t, tuple) else t
RE_DESIGNACION = re.compile('^(Ley\\s+\\d+/\\d{4}|Real\\s+Decreto(?:-ley)?\\s+\\d+/\\d{4}|Orden\\s+[A-Z]{3,4}/\\d+/\\d{4}|Reglamento[^,]{0,40}\\d+/\\d{4}|Directiva[^,]{0,30}\\d+/\\d+/[A-Z]{2})$')

def alias_de_titulo(titulo: str | None) -> list[str]:
    if not titulo:
        return []
    cabeza = titulo.split(',')[0].strip()
    return [cabeza] if RE_DESIGNACION.match(cabeza) else []
